 74:   for (let i = 0; i < text.length; i++) {
 75:     const ch = text[i];
 76:     if (q) { if (ch === '"') { if (text[i + 1] === '"') { f += '"'; i++; } else q = false; } else f += ch; }
 77:     else if (ch === '"') q = true;
 78:     else if (ch === ',') { row.push(f); f = ''; }
 79:     else if (ch === '\n') { row.push(f); rows.push(row); row = []; f = ''; }
 80:     else if (ch !== '\r') f += ch;
 81:   }
 82:   if (f !== '' || row.length) { row.push(f); rows.push(row); }
 83:   return rows.filter(r => r.length > 1 || r[0] !== '');
 84: }
